mapper.select:
select distinct tii.id, tii.BOOKSET_ID booksetId, tii.index_year indexYear, tii.index_type indexType, tii.tz_rank tzRank, tii.tz_type tzType, rpi.PROD_NAME prodName, tii.hold_share holdShare, tii.proportion_share proportionShare, tii.STATUS status, tii.UPDATE_TIME updateTime, tii.UPDATE_USER updateUser from TOP_INVESTOR_INFORMATION tii left join V_REP_PROD_INFO rpi on tii.BOOKSET_ID = rpi.PROD_ID
AND tii.BOOKSET_ID in
#{item}
AND tii.index_type =#{indexType}
AND tii.STATUS=#{status}
AND tii.index_year=#{indexYear}
union all select distinct tiih.id, tiih.BOOKSET_ID booksetId, tiih.index_year indexYear, tiih.index_type indexType, tiih.tz_rank tzRank, tiih.tz_type tzType, rpi.PROD_NAME prodName, tiih.hold_share holdShare, tiih.proportion_share proportionShare, tiih.STATUS status, tiih.UPDATE_TIME updateTime, tiih.UPDATE_USER updateUser from TOP_INVESTOR_INFORMATION_HIS tiih left join V_REP_PROD_INFO rpi on tiih.BOOKSET_ID = rpi.PROD_ID
AND tiih.BOOKSET_ID in
#{item}
AND tiih.index_type =#{indexType}
AND tiih.STATUS=#{status}
AND tiih.index_year=#{indexYear}
order by updateTime desc
